def trace_count(board, word):
    rows, cols = len(board), len(board[0])
    ways = {(i, j): 1 for i in range(rows) for j in range(cols) if board[i][j] == word[0]}
    for ch in word[1:]:
        nxt = {}
        for (i, j), w in ways.items():
            for a, b in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):
                if 0 <= a < rows and 0 <= b < cols and board[a][b] == ch:
                    nxt[(a, b)] = (nxt.get((a, b), 0) + w) % MOD
        ways = nxt
    return sum(ways.values()) % MOD

